import * as THREE from 'three';
export function makeControls({player,camera,dom,clamp}){const keys=new Set();let yaw=Math.PI,pitch=0,lock=false;dom.onclick=()=>dom.requestPointerLock?.();document.onpointerlockchange=()=>lock=document.pointerLockElement===dom;document.addEventListener('mousemove',e=>{if(!lock)return;yaw-=e.movementX*.0023;pitch-=e.movementY*.002;pitch=Math.max(-1.15,Math.min(1.15,pitch));player.rotation.y=yaw;camera.rotation.x=pitch;});addEventListener('keydown',e=>keys.add(e.code));addEventListener('keyup',e=>keys.delete(e.code));const clock=new THREE.Clock();function tick(){const dt=Math.min(.05,clock.getDelta()),spd=keys.has('ShiftLeft')?4.2:2.7,m=new THREE.Vector3();if(keys.has('KeyW'))m.z-=1;if(keys.has('KeyS'))m.z+=1;if(keys.has('KeyA'))m.x-=1;if(keys.has('KeyD'))m.x+=1;if(m.lengthSq()){m.normalize().multiplyScalar(spd*dt).applyAxisAngle(new THREE.Vector3(0,1,0),player.rotation.y);player.position.add(m);if(clamp){player.position.x=Math.max(clamp.minX,Math.min(clamp.maxX,player.position.x));player.position.z=Math.max(clamp.minZ,Math.min(clamp.maxZ,player.position.z));}}requestAnimationFrame(tick)}tick();}